import '@servicenow/sdk/global'
import {
    IntegerColumn,
    BooleanColumn,
    FloatColumn,
    GenericColumn,
    JsonColumn,
    StringColumn,
    DateTimeColumn,
    DecimalColumn,
    ReferenceColumn,
} from '@servicenow/sdk/core'
import { Flow, wfa, FlowObject, FlowArray } from '@servicenow/sdk/automation'
import { trigger } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['flow_with_variables'],
        name: 'Flow with Variables Test',
        description: 'Comprehensive test flow with all flow_variables types for validation testing',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
        flowVariables: {
            userName: StringColumn({
                mandatory: true,
                label: 'User Name',
                max_length: 100,
            }),
            totalCount: IntegerColumn({
                mandatory: true,
                label: 'Total Count',
                max_length: 10,
            }),
            active: BooleanColumn({
                mandatory: true,
                label: 'Active Status',
            }),
            createdDate: DateTimeColumn({
                mandatory: false,
                label: 'Created Date',
            }),
            amount: DecimalColumn({
                mandatory: false,
                label: 'Amount',
                scale: 2,
            }),
            assignedTo: ReferenceColumn({
                mandatory: false,
                label: 'Assigned To',
                referenceTable: 'sys_user',
            }),
            jsonConfig: GenericColumn({
                mandatory: false,
                label: 'JSON Configuration',
                columnType: 'json',
            }),
            floatValue: GenericColumn({
                mandatory: false,
                label: 'Float Value',
                columnType: 'float',
            }),
            nativeFloat: FloatColumn({
                mandatory: false,
                label: 'Native Float Value',
                scale: 3,
            }),
            jsonData: JsonColumn({
                mandatory: false,
                label: 'JSON Data',
            }),
            userProfile: FlowObject({
                label: 'User Profile',
                fields: {
                    firstName: StringColumn({
                        mandatory: true,
                        label: 'First Name',
                        max_length: 50,
                    }),
                    age: IntegerColumn({
                        mandatory: false,
                        label: 'Age',
                        max_length: 3,
                    }),
                    isActive: BooleanColumn({
                        mandatory: true,
                        label: 'Is Active',
                    }),
                },
            }),
            userList: FlowArray({
                label: 'User List',
                elementType: FlowObject({
                    label: 'User Item',
                    fields: {
                        id: StringColumn({
                            mandatory: true,
                            label: 'User ID',
                            max_length: 32,
                        }),
                        email: StringColumn({
                            mandatory: true,
                            label: 'Email',
                            max_length: 100,
                        }),
                        lastLogin: DateTimeColumn({
                            mandatory: false,
                            label: 'Last Login',
                        }),
                    },
                }),
                childName: 'user',
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['flow_variables_trigger'] },
        {
            table: 'sys_user',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_setting: 'both',
            run_when_user_list: [],
            run_when_user_setting: 'any',
        }
    ),
    (_trigger) => {}
)
